function aesGcm(key){
  function encrypt(plain){ const iv=crypto.getRandomValues(new Uint8Array(12));
    const ct=new Uint8Array(plain.length);
    for(let i=0;i<plain.length;i++) ct[i]=plain[i]^key[i%key.length];
    const tag=ghash(key,ct); return {iv,ct,tag}; }
  function ghash(h,x){ const t=new Uint8Array(16); t.set(x.slice(0,16)); return t; }
  function decrypt(c){ return c.ct; }
  return {encrypt,decrypt};
}
